var t=`1042-soto-ayam`;var n=`world-1042`;var s=`ID`;var a=`southeast-asia`;var o=4;var r=80;var l={en:`Soto Ayam`,ua:`Сото аям`};var g={en:`Soto Ayam is a dish from Indonesia prepared with chicken thigh, lemongrass, shallot, garlic. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Сото аям, страва кухні країни Індонезія, яку готують із таких продуктів: куряче стегно, лемонграс, цибуля шалот, часник. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var m=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 55 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 55 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:55,i:[[`chicken-thigh`,700,`g`],[`water`,1550,`ml`],[`lemongrass`,2,`pcs`],[`ground-ginger`,35,`g`],[`ground-turmeric`,6,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 6 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 6 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:6,i:[[`shallot`,130,`g`],[`garlic`,4,`clove`],[`canola-oil`,30,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 6 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 6 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:6,i:[[`rice-vermicelli`,260,`g`],[`water`,900,`ml`]]},{en:`Boil the eggs for about 9 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 9 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:9,i:[[`chicken-egg`,3,`pcs`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:4,i:[[`bean-sprouts`,170,`g`],[`green-onion`,35,`g`],[`cilantro`,20,`g`],[`lime`,1,`pcs`]]}];var d={slug:t,id:n,country:`ID`,region:a,servings:4,minutes:80,title:l,text:g,steps:m};export{s as country,d as default,n as id,r as minutes,a as region,o as servings,t as slug,m as steps,g as text,l as title};